110	func openZipReader(path string) (*zip.ReadCloser, error) {
111		reader, err := zip.OpenReader(path)
112		if err == nil {
113			return reader, nil
114		}
115		hasEOCD, probeErr := fileHasEOCD(path)
116		if probeErr == nil && !hasEOCD {
117			return nil, fmt.Errorf("invalid Zip archive: Could not find EOCD")
118		}
119		return nil, fmt.Errorf("invalid Zip archive: %s", err.Error())
120	}
