122	func fileHasEOCD(path string) (bool, error) {
123		file, err := os.Open(path)
124		if err != nil {
125			return false, err
126		}
127		defer file.Close()
128	
129		info, err := file.Stat()
130		if err != nil {
131			return false, err
132		}
133	
134		const maxEOCDSearch = 22 + 65535
135		size := info.Size()
136		searchSize := size
137		if searchSize > maxEOCDSearch {
138			searchSize = maxEOCDSearch
139		}
140	
141		buf := make([]byte, searchSize)
142		if _, err := file.ReadAt(buf, size-searchSize); err != nil && err != io.EOF {
143			return false, err
144		}
145		for i := len(buf) - 4; i >= 0; i-- {
146			if binary.LittleEndian.Uint32(buf[i:i+4]) == 0x06054b50 {
147				return true, nil
148			}
149		}
150		return false, nil
151	}
