153	func parseAESExtra(extra []byte) (*aesInfo, error) {
154		for len(extra) >= 4 {
155			headerID := binary.LittleEndian.Uint16(extra[:2])
156			dataSize := int(binary.LittleEndian.Uint16(extra[2:4]))
157			extra = extra[4:]
158			if len(extra) < dataSize {
159				return nil, fmt.Errorf("invalid Zip archive: truncated extra field")
160			}
161			data := extra[:dataSize]
162			extra = extra[dataSize:]
163			if headerID != 0x9901 {
164				continue
165			}
166			if len(data) < 7 {
167				return nil, fmt.Errorf("invalid Zip archive: invalid AES extra field")
168			}
169			info := &aesInfo{
170				version:      binary.LittleEndian.Uint16(data[:2]),
171				strength:     data[4],
172				actualMethod: binary.LittleEndian.Uint16(data[5:7]),
173			}
174			switch info.strength {
175			case 1:
176				info.keyLength = 16
177				info.saltLength = 8
178				info.label = "AES128"
179			case 2:
180				info.keyLength = 24
181				info.saltLength = 12
182				info.label = "AES192"
183			case 3:
184				info.keyLength = 32
185				info.saltLength = 16
186				info.label = "AES256"
187			default:
188				return nil, fmt.Errorf("invalid Zip archive: unsupported AES strength")
189			}
190			return info, nil
191		}
192		return nil, fmt.Errorf("invalid Zip archive: missing AES metadata")
193	}
